import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;

public class ChunkedReaderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static InputStream stream(String text) {
        return new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8));
    }

    static Object readAll(String text) {
        try {
            return ChunkedReader.readAll(stream(text));
        } catch (Throwable t) {
            return "readAll threw " + t.getClass().getSimpleName();
        }
    }

    static Object lengthOf(String text) {
        Object result = readAll(text);
        return (result instanceof String) ? ((String) result).length() : result;
    }

    static Object countLines(String text) {
        try {
            return ChunkedReader.countLines(stream(text));
        } catch (Throwable t) {
            return "countLines threw " + t.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("readAll of a short message", "Hello, sockets!", readAll("Hello, sockets!"));
        check("readAll of an empty stream", "", readAll(""));

        String big = "abcde".repeat(1000);
        check("readAll keeps looping past one buffer", 5000, lengthOf(big));
        check("readAll of a long stream is exact", Boolean.TRUE,
                Boolean.valueOf(big.equals(readAll(big))));

        String accented = "caf\u00e9 latte";
        check("readAll decodes multi-byte UTF-8", 10, lengthOf(accented));

        check("countLines with a trailing newline", 3, countLines("one\ntwo\nthree\n"));
        check("countLines without a trailing newline", 3, countLines("one\ntwo\nthree"));
        check("countLines of an empty stream", 0, countLines(""));
        check("countLines counts blank lines too", 2, countLines("\n\n"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

